// Independent SDK scopes not covered by the original password-only policy.
#define WANGSHU_LEARNING_FIXTURES_ONLY
#include "learning_tsf_test.cpp"
int main(){
    test("PRIVATE selection commits usable input without learning selected word",[]{Fixture f;f.context->doc.scope=IS_PRIVATE;f.type();bool inserted=f.key(VK_SPACE);WindowsPersonalTestAccess::idle(f.service);expect(inserted&&f.context->doc.text!=L"beforenihaoafter"&&f.store->readLearningFresh().data.entries.empty(),"PRIVATE field blocked ordinary input or learned selected word");});
    test("PRIVATE candidates use basic Chinese without personal ranking overlay",[]{Fixture f;f.context->doc.scope=IS_PRIVATE;f.type();expect(f.key(VK_SPACE)&&f.context->doc.text==L"before你好after","PRIVATE input used personalized vocabulary instead of basic Chinese");});
    test("PRIVATE explicit pin cannot save current private-field candidate",[]{Fixture f;f.context->doc.scope=IS_PRIVATE;f.type();expect(FAILED(WindowsPersonalTestAccess::action(f.service,f.context,0,LearningCommand::Pin))&&f.store->readLearningFresh().data.entries.empty(),"Private field allowed explicit candidate data capture");});
    test("PRIVATE voice preflight refuses before any microphone or recognizer",[]{Fixture f;f.context->doc.scope=IS_PRIVATE;auto* guard=new VoiceGuard(f.context);auto result=guard->DoEditSession(891);guard->Release();expect(FAILED(result),"Private voice scope was accepted");});
    test("queued personal candidate is rejected after host marks same field PRIVATE",[]{Fixture f;f.type();f.context->deferred=true;f.choose();auto before=f.context->doc.text;f.context->doc.scope=IS_PRIVATE;auto results=f.context->flush();WindowsPersonalTestAccess::idle(f.service);expect(FAILED(results[0])&&f.context->doc.text==before&&f.store->readLearningFresh().data.entries.empty(),"Stale personal candidate inserted or learned in newly private field");});
    test("scope becoming PRIVATE during applied write prevents background learning",[]{Fixture f;f.type();f.context->doc.privateAfterWrite=true;expect(f.key('2')&&f.context->doc.text==L"beforesecondafter"&&f.count("second")==0,"Post-write PRIVATE transition learned or replayed applied text");});
    for(auto scope:std::vector<std::pair<const char*,InputScope>>{{"NUMERIC_PIN",IS_NUMERIC_PIN},{"ALPHANUMERIC_PIN",IS_ALPHANUMERIC_PIN},{"ALPHANUMERIC_PIN_SET",IS_ALPHANUMERIC_PIN_SET}}){
        test(scope.first,[scope]{Fixture f;f.type();f.context->doc.scope=scope.second;auto before=f.context->doc.text;bool inserted=f.key('2');auto* guard=new VoiceGuard(f.context);auto voice=guard->DoEditSession(891);guard->Release();expect(!inserted&&FAILED(voice)&&f.context->doc.text==before&&f.count("second")==0,"PIN scope accepted IME candidate/voice or learned private content");});
    }
    test("normal-field learning resumes after leaving PRIVATE without retaining private term",[]{Fixture f;f.context->doc.scope=IS_PRIVATE;f.type();f.key(VK_SPACE);WindowsPersonalTestAccess::idle(f.service);f.context->doc.scope=IS_DEFAULT;f.type();expect(WindowsPersonalTestAccess::first(f.service)=="first"&&f.key('2')&&f.count("second")==1&&f.count("first")==0&&f.store->readLearningFresh().data.entries.size()==1,"PRIVATE policy stuck or private word was learned");});
    test("existing speech review Enter is rejected when same field becomes PRIVATE",[]{Fixture f;TextServiceTestAccess::stageVoice(f.service,f.context,"pending-speech");f.context->doc.scope=IS_PRIVATE;auto before=f.context->doc.text;bool consumed=f.key(VK_RETURN);expect(consumed&&f.context->doc.text==before&&!TextServiceTestAccess::hasVoice(f.service),"Private speech confirmation inserted text, retained review or forwarded Enter");});
    test("existing speech candidate Finalize cannot insert into newly PRIVATE field",[]{Fixture f;TextServiceTestAccess::stageVoice(f.service,f.context,"pending-speech");f.context->doc.scope=IS_PRIVATE;auto before=f.context->doc.text;auto result=f.choose(0);expect(FAILED(result)&&f.context->doc.text==before&&!TextServiceTestAccess::hasVoice(f.service),"Hosted speech candidate bypassed private-field scope");});
    test("private-scope fixtures release service and background ownership",[]{expect(objectCount==0,"Private scope fixture leaked owned COM state");});
    std::cout<<"RESULT passed="<<passed<<" failed="<<failed<<" total="<<(passed+failed)<<"; actual production PE TSF with SDK PRIVATE/PIN scope fixtures, real Windows NOT_RUN"<<std::endl;return failed?1:0;
}
